  "/sw.js": { type: "text/javascript; charset=utf-8", binary: false, body: "// Caches the app shell so the page opens instantly on a phone.\n// The API (/eve/) is never cached: conversations and voice must always be live.\nconst SHELL = \"assistant-shell-v1\";\nconst ASSETS = [\"/\", \"/manifest.webmanifest\", \"/icon-192.png\", \"/icon-512.png\"];\n\nself.addEventListener(\"install\", (event) => {\n  event.waitUntil(caches.open(SHELL).then((cache) => cache.addAll(ASSETS)).then(() => self.skipWaiting()));\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== SHELL).map((k) => caches.delete(k))))\n      .then(() => self.clients.claim()),\n  );\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  const url = new URL(event.request.url);\n  if (event.request.method !== \"GET\" || url.origin !== self.location.origin) return;\n  if (url.pathname.startsWith(\"/eve/\")) return; // always network\n  event.respondWith(\n    fetch(event.request)\n      .then((response) => {\n        const copy = response.clone();\n        caches.open(SHELL).then((cache) => cache.put(event.request, copy));\n        return response;\n      })\n      .catch(() => caches.match(event.request).then((hit) => hit || Response.error())),\n  );\n});\n" },
